def compute_format_bits(ec_level, mask):
    # ec_level: 0:L,1:M,2:Q,3:H? Actually mapping: L=01, M=00, Q=11, H=10 (bits)
    ec_bits={'L':0b01,'M':0b00,'Q':0b11,'H':0b10}
    bits = (ec_bits[ec_level] << 3) | mask  # 5 bits
    # shift left 10
    data = bits << 10
    # generator polynomial 0x537 (binary 101 0011 0111)
    g=0x537
    for i in range(14,9,-1):
        if data & (1 << i):
            data ^= g << (i-10)
    # remainder is lower 10 bits
    remainder = data & 0x3ff
    format_bits = (bits << 10) | remainder
    # mask with 0x5412
    return format_bits ^ 0x5412

# extract format bits from matrix earlier (fmt_int)
fmt_int=10975
for level in ['L','M','Q','H']:
    for mask in range(8):
        fb=compute_format_bits(level,mask)
        if fb==fmt_int:
            print('found',level,mask)

